description:
A good theme uses one accent colour at three strengths. Write

```cpp
struct Color { float r, g, b, a; };

Color withAlpha(Color c, float a);
Color lighten(Color c, float amount);     // move each channel towards 1 by amount (0..1)
Color darken(Color c, float amount);      // move each channel towards 0 by amount (0..1)
std::vector<Color> accentStates(Color accent);   // { normal, hovered, active }
```

- `lighten(c, t)`: each of r, g, b becomes `x + (1 - x) * t`; `darken(c, t)`: `x * (1 - t)`. Alpha is unchanged.
- `accentStates`: normal is the accent at alpha 0.40; hovered is the accent at alpha 0.60; active is the accent lightened by 0.15 at alpha 1.0.

starter.solution.cpp:
#include <vector>

struct Color { float r, g, b, a; };

Color withAlpha(Color c, float a) { return c; }
Color lighten(Color c, float amount) { return c; }
Color darken(Color c, float amount) { return c; }
std::vector<Color> accentStates(Color accent) { return {}; }

solution.solution.cpp:
#include <vector>

struct Color { float r, g, b, a; };

Color withAlpha(Color c, float a) { c.a = a; return c; }

Color lighten(Color c, float t)
{
    return { c.r + (1 - c.r) * t, c.g + (1 - c.g) * t, c.b + (1 - c.b) * t, c.a };
}

Color darken(Color c, float t)
{
    return { c.r * (1 - t), c.g * (1 - t), c.b * (1 - t), c.a };
}

std::vector<Color> accentStates(Color accent)
{
    return { withAlpha(accent, 0.40f), withAlpha(accent, 0.60f), withAlpha(lighten(accent, 0.15f), 1.0f) };
}

unitTests:
bool near(const Color& c, float r, float g, float b, float a) { auto ok = [](float x, float y) { return x - y < 1e-5f && y - x < 1e-5f; }; return ok(c.r, r) && ok(c.g, g) && ok(c.b, b) && ok(c.a, a); }
TEST("alpha") { CHECK(near(withAlpha({ 0.1f, 0.2f, 0.3f, 1 }, 0.5f), 0.1f, 0.2f, 0.3f, 0.5f)); }
TEST("lighten and darken") { CHECK(near(lighten({ 0.5f, 0, 1, 0.7f }, 0.5f), 0.75f, 0.5f, 1, 0.7f)); CHECK(near(darken({ 0.5f, 1, 0, 0.7f }, 0.25f), 0.375f, 0.75f, 0, 0.7f)); }
TEST("accent states") { const auto s = accentStates({ 0.9f, 0.6f, 0.2f, 1 }); CHECK_EQ(s.size(), std::size_t{ 3 }); CHECK(near(s[0], 0.9f, 0.6f, 0.2f, 0.4f)); CHECK(near(s[1], 0.9f, 0.6f, 0.2f, 0.6f)); CHECK(near(s[2], 0.915f, 0.66f, 0.32f, 1.0f)); }

